CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261014194408_InitialBaseline') THEN
    CREATE TABLE "Planes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(100) NOT NULL,
        "Precio" numeric(10,2) NOT NULL,
        "LimiteUsuarios" integer NOT NULL,
        "LimiteAtributos" integer NOT NULL,
        "LimiteSucursales" integer NOT NULL,
        CONSTRAINT "PK_Planes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

