        CONSTRAINT "PK_Comercios" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Comercios_Planes_PlanId" FOREIGN KEY ("PlanId") REFERENCES "Planes" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

